arguments.command:
python3 -c "
import zipfile
with zipfile.ZipFile('/root/project_proposal_ready.hwpx') as z:
    for name in z.namelist():
        if not name.endswith('.xml'):
            continue
        content = z.read(name).decode('utf-8', errors='ignore')
        # Check linesegarray in any paragraph that contains placeholders or phase data
        import re
        # Find all hp:p elements
        paras = re.findall(r'<hp:p[^>]*>.*?</hp:p>', content, re.DOTALL)
        for para in paras:
            if 'linesegarray' in para.lower():
                # Check if this is a modified paragraph (has replaced data)
                if any(k in para for k in ['스마트', '디지털', '2026', '2027', '최수민', '요구사항', '시스템 개발', '파일럿']):
                    print(f'Stale linesegarray in modified paragraph in {name}:', para[:200])
                else:
                    print(f'OK: linesegarray in unmodified paragraph in {name}')
"

